def php(s): return '<?php\n'+s+'\n'
def go(s): return 'package main\nimport "fmt"\nfunc main() {\n'+s+'\n}\n'
def rust(s): return 'fn main() {\n'+s+'\n}\n'
def kotlin(s): return 'fun main() {\n'+s+'\n}\n'
course('php','PHP','php','Examples use PHP 8.2 or later and the command line.','Install PHP 8.2 or later. Save each example as lesson.php and run php lesson.php. These are local programs, not a server for this learning site.','PHP is a language often used to build the part of a website that works on a server.',[
L('first-message','A first message','echo shows text. Text is a string: a row of letters inside quotes.',php('echo "Hello, Asha!\\n";'),'Hello, Asha!','Change the name in the message.','End the echo statement with a semicolon.'),
L('variables','Named values','A variable keeps a value under a name. PHP variable names start with a dollar sign.',php('$pencils = 3;\necho $pencils + 2;'),'5','Change pencils to 6 and predict the sum.','Use $pencils every time you read that variable.'),
L('joining-text','Join pieces of text','The dot joins text in PHP. Joining is called concatenation.',php('$name = "Ravi";\necho "Hi, " . $name;'),'Hi, Ravi','Add an exclamation mark with another dot.','Use a dot to join text; plus is for numbers.'),
L('choices','Choose a message','if checks a rule. The >= sign means at least.',php('$score = 8;\nif ($score >= 5) { echo "Pass"; } else { echo "Try again"; }'),'Pass','Try a score of 3.','Put the test inside parentheses after if.'),
L('lists','Store a short list','An array can keep values in order. Its first numbered position is zero.',php('$pets = ["cat", "dog"];\necho $pets[1];'),'dog','Add fish and read position 2.','Position 1 is the second item, not the first.'),
L('foreach','Visit each item','foreach repeats its block for every item in an array.',php('foreach ([2, 4] as $n) { echo $n . "\\n"; }'),'2\n4','Add 6 to the list.','Use the loop variable inside the block, not the whole array.'),
L('functions','Name a set of steps','A function takes an input and can return a result. return sends the answer back.',php('function twice(int $n): int { return $n * 2; }\necho twice(4);'),'8','Call twice with 7.','Printing inside a function and returning a value are different actions.'),
L('named-keys','Look up a named value','An array can use text keys. A key is a label used to find a value.',php('$book = ["title" => "Moon Trip", "pages" => 24];\necho $book["title"];'),'Moon Trip','Read the pages key instead.','Use => between a key and its value.'),
L('strict-checks','Check value and type','The === test checks both the value and its type. Text 5 is not the same type as number 5.',php('echo 5 === "5" ? "same" : "different";'),'different','Compare 5 with 5 instead.','Loose equality can convert types; === avoids that surprise.'),
L('missing-values','Choose a fallback','The ?? operator uses a fallback when a value is missing or null.',php('$settings = [];\necho $settings["colour"] ?? "blue";'),'blue','Add a colour key with red.','An empty string is still a value; ?? does not replace it.'),
L('json','Make JSON text','JSON is a text format for data. json_encode turns this small array into JSON.',php('echo json_encode(["score" => 5], JSON_THROW_ON_ERROR);'),'{"score":5}','Add a name key to the array.','JSON uses quoted field names; let the tool make the text.'),
L('classes','Keep data in an object','A class is a plan for objects. Each object can have its own stored fields.',php('class Badge { public string $colour = "blue"; }\n$badge = new Badge();\necho $badge->colour;'),'blue','Change the object colour to red.','Use -> to read a field on an object, not array brackets.')])
course('ruby','Ruby','ruby','Examples use Ruby 3.1 or later.','Install Ruby 3.1 or later. Save one example as lesson.rb and run ruby lesson.rb in a terminal.','Ruby is a language for writing clear scripts and apps, including web apps.',[
L('first-message','Print a message','puts prints a value and moves to a new line. Quoted letters make a string.','puts "Hello, Asha!"','Hello, Asha!','Replace Asha with your name.','Keep matching quotes around text.'),
L('variables','Keep a named number','Ruby variables give names to values. The plus sign adds numbers.','pencils = 3\nputs pencils + 2','5','Change the starting count to 6.','Do not put number values in quotes when you want maths.'),
L('text','Put a value in text','Inside double quotes, #{name} places a value into text.','name = "Ravi"\nputs "Hi, #{name}!"','Hi, Ravi!','Try a different name.','Single-quoted strings do not expand #{name}.'),
L('choices','Make a choice','if runs a block when its rule is true. Ruby closes this block with end.','score = 8\nif score >= 5\n  puts "Pass"\nelse\n  puts "Try again"\nend','Pass','Try score = 3.','Remember the final end for the if block.'),
L('arrays','Read a list item','An array keeps values in order. The first index is zero.','pets = ["cat", "dog"]\nputs pets[1]','dog','Read position 0.','An index past the list gives nil, not a new item.'),
L('each','Repeat with a block','each visits each item. The name between vertical bars is the current item.','[2, 4].each do |n|\n  puts n\nend','2\n4','Add 6 to the array.','Use the current item n inside the block.'),
L('methods','Write a method','A method is a named set of steps. Ruby returns the last expression by default.','def twice(n)\n  n * 2\nend\nputs twice(4)','8','Call twice(7).','Keep the calculation as the last expression if it is the answer.'),
L('hashes','Find a value by label','A hash pairs keys with values. :title is a symbol used as a key.','book = { title: "Moon Trip", pages: 24 }\nputs book[:title]','Moon Trip','Read :pages instead.','The symbol :title and the string "title" are different keys.'),
L('map','Change every item','map makes a new array from the result of a block for each item.','doubled = [2, 3].map { |n| n * 2 }\nputs doubled.join(", ")','4, 6','Multiply each item by 3.','map returns a new array; it does not replace the old one.'),
L('nil','Handle no value','nil means no value. The || operator chooses the right side when the left side is nil or false.','name = nil\nputs name || "Guest"','Guest','Give name the text Asha.','Zero and empty strings count as true in Ruby.'),
L('classes','Make a small object','A class groups data and methods. initialize runs when a new object is made.','class Badge\n  def initialize(colour)\n    @colour = colour\n  end\n  def label\n    @colour\n  end\nend\nputs Badge.new("blue").label','blue','Make a red badge.','@colour belongs to the object; colour is only a local input.'),
L('errors','Handle an expected error','rescue handles an error of a named kind. Integer tries to read a whole number from text.','begin\n  puts Integer("cat")\nrescue ArgumentError\n  puts "Use a whole number"\nend','Use a whole number','Try the text "12".','Handle the error you expect instead of hiding every error.')])
course('go','Go','go','Examples use Go 1.22 or later.','Install Go 1.22 or later. Save one complete example as lesson.go and run go run lesson.go.','Go is a language for small tools and fast network services. It checks types before a program runs.',[
L('first-message','Print a greeting','main is where this Go program starts. fmt.Println prints values on a new line.',go('fmt.Println("Hello, Asha!")'),'Hello, Asha!','Change the greeting text.','Keep package main and func main in a runnable program.'),
L('variables','Name a number','The := sign makes a new local variable and chooses its type from the value.',go('pencils := 3\nfmt.Println(pencils + 2)'),'5','Start with 6 pencils.','Use = to change an existing variable; := declares a new one.'),
L('types','Use a clear type','A type says what kind of value fits a variable. int stores whole numbers.',go('var score int = 8\nfmt.Println(score)'),'8','Change the score to 9.','An int cannot store text like "eight".'),
L('choices','Choose a path','if checks a true-or-false rule. Go uses braces around the steps.',go('score := 8\nif score >= 5 { fmt.Println("Pass") } else { fmt.Println("Try again") }'),'Pass','Try score 3.','Put the opening brace on the if line.'),
L('loops','Repeat steps','A for loop can count from a start value until a test becomes false.',go('for n := 1; n <= 3; n++ { fmt.Println(n) }'),'1\n2\n3','Stop at 4 instead.','Check whether your last number should use < or <=.'),
L('slices','Keep a growing list','A slice is a view of a list of values. append returns a slice with more items.',go('scores := []int{4, 5}\nscores = append(scores, 8)\nfmt.Println(scores)'),'[4 5 8]','Append 9 too.','Keep the slice returned by append.'),
L('range','Visit list values','range gives an index and a value for each slice item. _ ignores the index.',go('for _, pet := range []string{"cat", "dog"} { fmt.Println(pet) }'),'cat\ndog','Add fish to the slice.','A single range variable is the index, not the value.'),
L('maps','Look up a key','A map links a key to a value. The key below is a name and the value is a count.',go('pencils := map[string]int{"Asha": 3}\nfmt.Println(pencils["Asha"])'),'3','Add Ravi with 5 pencils.','Check the second lookup result when you need to know if a key exists.'),
L('functions','Use a small function','A function can take a number and return a number. This example stores a function in twice.',go('twice := func(n int) int { return n * 2 }\nfmt.Println(twice(4))'),'8','Call twice(7).','Write the return type after the input list.'),
L('structs','Group related fields','A struct groups named fields. Here a book has one title and one page count.',go('type Book struct { Title string; Pages int }\nbook := Book{Title: "Moon Trip", Pages: 24}\nfmt.Println(book.Title)'),'Moon Trip','Print book.Pages.','Exported field names begin with a capital letter.'),
L('pointers','Change an original value','A pointer stores an address. & gets an address, and * reaches the value there.',go('score := 3\nplace := &score\n*place = 7\nfmt.Println(score)'),'7','Store 9 through the pointer.','Do not read through a nil pointer.'),
L('channels','Pass a value through a channel','A channel carries values between parts of a program. A buffered channel can hold one value here.',go('scores := make(chan int, 1)\nscores <- 8\nfmt.Println(<-scores)'),'8','Send 6 instead.','An unbuffered send needs a receiver ready, or it will wait.')])
course('rust','Rust','rust','Examples use stable Rust with the 2021 edition or later.','Install stable Rust. Save each example as lesson.rs, run rustc lesson.rs, then run the created program.','Rust is a language that checks many memory mistakes before a program runs. It is used for tools and fast systems.',[
L('first-message','Print a greeting','println! prints text and starts a new line. main is the program entry point.',rust('println!("Hello, Asha!");'),'Hello, Asha!','Change the greeting.','println! has an exclamation mark because it is a macro.'),
L('variables','Keep a value','let creates a name for a value. Values cannot be changed unless you ask for mut.',rust('let pencils = 3;\nprintln!("{}", pencils + 2);'),'5','Change the starting count.','A plain let binding cannot be assigned a new value.'),
L('mutability','Change a value','mut means this binding may change. It makes the choice to change data clear.',rust('let mut score = 3;\nscore += 2;\nprintln!("{}", score);'),'5','Add 4 instead.','Use mut only when the value needs to change.'),
L('choices','Pick a value with if','if can produce a value. Both branches here return text of the same type.',rust('let score = 8;\nlet message = if score >= 5 { "Pass" } else { "Try again" };\nprintln!("{}", message);'),'Pass','Try a score of 3.','Both branches used as a value must have matching types.'),
L('loops','Count with a range','1..=3 includes both ends. A for loop visits each number in the range.',rust('for n in 1..=3 { println!("{}", n); }'),'1\n2\n3','End at 4.','1..3 stops before 3; ..= includes the end.'),
L('vectors','Grow a list','A Vec stores values in order. push adds a value at the end.',rust('let mut scores = vec![4, 5];\nscores.push(8);\nprintln!("{:?}", scores);'),'[4, 5, 8]','Push 9 as well.','The vector must be mutable to push a new item.'),
L('functions','Return a result','The last expression can be a function result. It has no trailing semicolon.', 'fn twice(n: i32) -> i32 { n * 2 }\nfn main() { println!("{}", twice(4)); }','8','Call twice(7).','A semicolon after n * 2 turns it into a statement with no returned number.'),
L('ownership','Move ownership','A String owns its text. Assigning it to another variable moves that ownership.',rust('let first = String::from("Asha");\nlet second = first;\nprintln!("{}", second);'),'Asha','Try reading first after the move and read the compiler message.','Do not use a String binding after its value has moved.'),
L('borrowing','Read without taking ownership','A reference borrows a value. It lets code read the value while its owner keeps it.',rust('let name = String::from("Asha");\nlet borrowed = &name;\nprintln!("{} {}", borrowed, name);'),'Asha Asha','Borrow a different name.','A reference must not outlive the value it points to.'),
L('option','Handle a missing value','Option holds Some(value) or None. unwrap_or gives a fallback for None.',rust('let score: Option<i32> = None;\nprintln!("{}", score.unwrap_or(0));'),'0','Use Some(8) instead.','unwrap can panic on None; check it or use a fallback.'),
L('result','Handle a failed action','Result holds Ok for success or Err for failure. Parsing text can fail.',rust('match "cat".parse::<i32>() {\n Ok(n) => println!("{}", n),\n Err(_) => println!("Use a number"),\n}'),'Use a number','Try parsing "12".','Do not assume every text value is a valid number.'),
L('structs','Group named data','A struct describes named fields. Each Book value can hold its own title.',rust('struct Book { title: String }\nlet book = Book { title: String::from("Moon Trip") };\nprintln!("{}", book.title);'),'Moon Trip','Add a pages field with type u32.','Supply every required field when making a struct.')])
course('swift','Swift','swift','Examples use Swift 5.9 or later.','Install Swift or use Xcode on a Mac. Save each example as lesson.swift and run swift lesson.swift.','Swift is a language used for Apple apps and other programs. It has clear tools for values that may be missing.',[
L('first-message','Print a greeting','print shows a value and ends the line. Text inside quotes is a String.','print("Hello, Asha!")','Hello, Asha!','Use your own name.','Keep quotes around a text value.'),
L('constants','Keep a fixed value','let makes a constant. Its value cannot be changed after it is set.','let pencils = 3\nprint(pencils + 2)','5','Start with 6 pencils.','Use var when a stored value must change later.'),
L('variables','Change a value','var makes a variable that can change. += adds to its current value.','var score = 3\nscore += 2\nprint(score)','5','Add 4 instead of 2.','An Int stores whole numbers, not text.'),
L('text','Put a value in text','A backslash followed by parentheses places a value inside a Swift string.','let name = "Ravi"\nprint("Hi, \\(name)!")','Hi, Ravi!','Put a score into a message too.','Use \\(name), not JavaScript ${name} syntax.'),
L('choices','Choose a message','if checks a Boolean rule, which is either true or false.','let score = 8\nif score >= 5 { print("Pass") } else { print("Try again") }','Pass','Try score 3.','Swift if needs a Boolean; a bare number is not a condition.'),
L('arrays','Read an array item','An array keeps values of one type in order. Position zero is first.','let pets = ["cat", "dog"]\nprint(pets[1])','dog','Read pets[0].','An index outside the array stops the program.'),
L('loops','Walk through a range','The closed range 1...3 includes 1, 2 and 3.','for n in 1...3 { print(n) }','1\n2\n3','Try 1...4.','1..<3 leaves out 3; three dots include it.'),
L('functions','Name reusable steps','A function takes an input and returns a typed result. _ lets callers omit the input label.','func twice(_ n: Int) -> Int { n * 2 }\nprint(twice(4))','8','Call twice(7).','The returned value must match the declared return type.'),
L('optionals','Choose a fallback','An optional can hold a value or nil. ?? gives a fallback when it is nil.','let name: String? = nil\nprint(name ?? "Guest")','Guest','Set name to "Asha".','Avoid force-unwrapping with ! when the value may be nil.'),
L('optional-binding','Read only when present','if let unwraps an optional only when it contains a value.','let score: Int? = 8\nif let value = score { print(value) }','8','Try nil and observe that nothing prints.','The unwrapped value exists only inside its block.'),
L('structs','Group fields with a struct','A struct groups related values. A Book has a title and a page count.','struct Book { var title: String; var pages: Int }\nlet book = Book(title: "Moon Trip", pages: 24)\nprint(book.pages)','24','Change the page count.','A let struct value cannot have its stored fields changed.'),
L('enums','Name a few choices','An enum lists a fixed set of choices. switch handles each possible choice.','enum Light { case red, green }\nlet light = Light.green\nswitch light {\ncase .red: print("Stop")\ncase .green: print("Go")\n}','Go','Set light to .red.','A switch over an enum must cover all cases.')])
course('kotlin','Kotlin','kotlin','Examples use Kotlin 1.9 or later on the JVM.','Install a JDK and Kotlin. Save lesson.kt, run kotlinc lesson.kt -include-runtime -d lesson.jar, then java -jar lesson.jar.','Kotlin is a language used for Android apps, server programs and small tools.',[
L('first-message','Print a greeting','main is the starting function. println prints a value on a new line.',kotlin('println("Hello, Asha!")'),'Hello, Asha!','Change the greeting.','A program needs a main function to start here.'),
L('values','Keep a fixed value','val gives a name to a value that cannot be reassigned.',kotlin('val pencils = 3\nprintln(pencils + 2)'),'5','Start with 6 pencils.','Use var only if the binding must change.'),
L('variables','Update a variable','var lets you assign a new value. += adds to the current number.',kotlin('var score = 3\nscore += 2\nprintln(score)'),'5','Add 4 instead.','A variable keeps its type even when its value changes.'),
L('text','Build a message','A dollar sign places a variable value inside a Kotlin string.',kotlin('val name = "Ravi"\nprintln("Hi, $name!")'),'Hi, Ravi!','Place a score in a message.','Use ${...} for an expression, not just $.'),
L('if-values','Choose a value','if can return a value. Both branches below produce a message.',kotlin('val score = 8\nval message = if (score >= 5) "Pass" else "Try again"\nprintln(message)'),'Pass','Try a score of 3.','An if used as a value needs an else branch.'),
L('lists','Read a list','listOf makes a read-only list. The first item has index zero.',kotlin('val pets = listOf("cat", "dog")\nprintln(pets[1])'),'dog','Read the first item.','Use a mutable list when you need add or remove operations.'),
L('ranges','Count with a range','The range 1..3 includes both ends. for reads each number.',kotlin('for (n in 1..3) println(n)'),'1\n2\n3','Change the end to 4.','1 until 3 leaves out 3.'),
L('functions','Write a short function','A function gives steps a name. This expression body returns n times two.',kotlin('fun twice(n: Int): Int = n * 2\nprintln(twice(4))'),'8','Call twice(7).','Write a type for each function input.'),
L('nullable','Handle no value','A question mark makes a type nullable. ?: supplies a fallback for null.',kotlin('val name: String? = null\nprintln(name ?: "Guest")'),'Guest','Use the name Asha.','The !! operator can crash when the value is null.'),
L('safe-calls','Read safely','?. only calls a property or method when the value is not null.',kotlin('val name: String? = null\nprintln(name?.length ?: 0)'),'0','Set name to "Asha" and predict its length.','A safe call may return null, so handle that result too.'),
L('data-classes','Keep related data','A data class stores fields and supplies useful data operations such as copy.',kotlin('data class Book(val title: String, val pages: Int)\nval book = Book("Moon Trip", 24)\nprintln(book.copy(pages = 30).pages)'),'30','Print the original book.pages too.','copy makes a new value; it does not change the original.'),
L('when','Match a choice','when picks a branch for a value. else handles the values not listed.',kotlin('val light = "green"\nprintln(when (light) { "red" -> "Stop"; "green" -> "Go"; else -> "Wait" })'),'Go','Try light = "yellow".','A when used as a value must cover every possibility.')])
